-- One agent is never booked twice at once (ADR 0032 §3). btree_gist gives uuid
-- an "=" in a GiST index; '[)' lets one meeting end at 20:00 and the next start
-- at 20:00. Only active rows: a cancelled or completed meeting frees its time.
-- Fails if dev/prod already holds an overlap — checked before applying (0 rows).
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA extensions;--> statement-breakpoint
ALTER TABLE "appointment" ADD CONSTRAINT "appointment_agent_no_overlap" EXCLUDE USING gist ("assigned_agent_id" WITH =, tstzrange("starts_at", "ends_at", '[)') WITH &&) WHERE (status IN ('scheduled', 'rescheduled') AND assigned_agent_id IS NOT NULL);--> statement-breakpoint
-- The reminder tick's sweep: active, unreminded, with a reminder asked for.
CREATE INDEX "appointment_reminder_due_idx" ON "appointment" USING btree ("starts_at") WHERE reminder_sent_at IS NULL AND reminder_minutes IS NOT NULL AND status IN ('scheduled', 'rescheduled');
